import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{C as n,c as e,o as h,ag as i,G as l}from"./chunks/mermaid.Bf0DxEx6.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"Google Colab","description":"没有显卡、不想装环境，也能在浏览器里跑 Python 并按需用上 GPU。这一页带你从第一个单元格，一路做到把结果存进 Drive、管好密钥、在 notebook 里调通 Gemini API。","frontmatter":{"title":"Google Colab","description":"没有显卡、不想装环境，也能在浏览器里跑 Python 并按需用上 GPU。这一页带你从第一个单元格，一路做到把结果存进 Drive、管好密钥、在 notebook 里调通 Gemini API。","domain":"product","tags":["colab","notebook","gpu"],"role":"tutorial","pageClass":"wide-figures"},"headers":[],"relativePath":"zh/products/gemini/colab.md","filePath":"zh/products/gemini/colab.md","lastUpdated":1795592559000}'),p={name:"zh/products/gemini/colab.md"};function k(r,s,o,d,g,E){const a=n("DocDiagram");return h(),e("div",null,[s[0]||(s[0]=i("",44)),l(a,{src:"/diagrams/google-colab-runtime.svg",alt:"这张图回答两个问题：你的代码到底跑在哪里；运行时断开之后，哪些东西还在，哪些没了。实线表示断开后仍然保留的关系，虚线表示断开后会消失的部分。左边是浏览器里的 notebook 界面，在你的电脑上，里面有单元格、输出和左侧栏，notebook 内容是在这里编辑的。中间上方是两个持久的位置：Google Drive 存放 notebook 文件与数据文件，GitHub 存放 notebook 副本与克隆下来的仓库。界面与 Drive 之间、界面与 GitHub 之间是实线双向箭头，断开后仍然保留。中间下方是云端的运行时虚拟机，代码实际运行在这里。它的算力类型可以是 CPU，也可以按需切换到 GPU 或 TPU，界面可以切换运行时类型。运行时里有三样东西在断开后会消失，用玫红色虚线框标出：内核进程与内存变量，例如变量和已导入的模块；临时磁盘，例如已安装的包和上传到运行时的文件；以及挂载状态。界面到运行时的连接也是虚线：界面把单元格代码发往运行时，运行时把输出送回界面。运行时经授权挂载后与 Drive 双向读写，这是虚线，因为断开后挂载失效。运行时可以从 GitHub 拉取 notebook 或仓库。右边是你电脑上的文件，原件留在你的电脑；上传到运行时的那份副本在临时磁盘上，断开后消失。Secrets 在你授权后把密钥交给运行时里的代码。本图省略了 Google 内部的基础设施、任何免费额度的具体数字，以及具体版本里才有的按钮与菜单名。",width:1020}),s[1]||(s[1]=i("",122))])}const C=t(p,[["render",k]]);export{b as __pageData,C as default};
